-- MCP OAuth for ChatGPT/Claude: personal grants independent of the existing smcp_ token.
-- Secrets are generated by the service and stored only as SHA-256 hashes. All transitions
-- that consume a code/request/refresh happen in one transaction under a row lock.

CREATE TABLE IF NOT EXISTS public.mcp_oauth_clients (
  client_id text PRIMARY KEY,
  client_name text NOT NULL CHECK (length(client_name) BETWEEN 1 AND 200),
  redirect_uris text[] NOT NULL CHECK (cardinality(redirect_uris) BETWEEN 1 AND 10),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS mcp_oauth_clients_created_idx ON public.mcp_oauth_clients(created_at);
CREATE TABLE IF NOT EXISTS public.mcp_oauth_requests (
  id text PRIMARY KEY,
  client_id text NOT NULL REFERENCES public.mcp_oauth_clients ON DELETE CASCADE,
  redirect_uri text NOT NULL,
  state text,
  challenge text NOT NULL CHECK (challenge ~ '^[A-Za-z0-9_-]{43}$'),
  resource text NOT NULL,
  scope text NOT NULL CHECK (scope IN ('mcp', 'mcp offline_access')),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL DEFAULT now() + interval '10 minutes',
  consumed_at timestamptz
);
CREATE TABLE IF NOT EXISTS public.mcp_oauth_connections (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  telegram_id bigint NOT NULL REFERENCES public.allowed_users(telegram_id) ON DELETE CASCADE,
  group_id text NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
  client_id text NOT NULL REFERENCES public.mcp_oauth_clients ON DELETE CASCADE,
  redirect_uri text NOT NULL,
  resource text NOT NULL,
  scope text NOT NULL CHECK (scope IN ('mcp', 'mcp offline_access')),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL DEFAULT now() + interval '30 days',
  last_seen_at timestamptz,
  revoked_at timestamptz
);
CREATE INDEX IF NOT EXISTS mcp_oauth_connections_owner_idx ON public.mcp_oauth_connections(telegram_id, created_at DESC);
CREATE INDEX IF NOT EXISTS mcp_oauth_connections_client_idx ON public.mcp_oauth_connections(client_id);
CREATE INDEX IF NOT EXISTS mcp_oauth_connections_expiry_idx ON public.mcp_oauth_connections(expires_at);
CREATE TABLE IF NOT EXISTS public.mcp_oauth_codes (
  code_hash text PRIMARY KEY CHECK (code_hash ~ '^[0-9a-f]{64}$'),
  connection_id uuid NOT NULL REFERENCES public.mcp_oauth_connections ON DELETE CASCADE,
  client_id text NOT NULL REFERENCES public.mcp_oauth_clients ON DELETE CASCADE,
  redirect_uri text NOT NULL,
  challenge text NOT NULL,
  resource text NOT NULL,
  expires_at timestamptz NOT NULL DEFAULT now() + interval '5 minutes',
  consumed_at timestamptz
);
CREATE TABLE IF NOT EXISTS public.mcp_oauth_tokens (
  token_hash text PRIMARY KEY CHECK (token_hash ~ '^[0-9a-f]{64}$'),
  connection_id uuid NOT NULL REFERENCES public.mcp_oauth_connections ON DELETE CASCADE,
  kind text NOT NULL CHECK (kind IN ('access', 'refresh')),
  expires_at timestamptz NOT NULL,
  consumed_at timestamptz
);
CREATE INDEX IF NOT EXISTS mcp_oauth_tokens_connection_idx ON public.mcp_oauth_tokens(connection_id);
CREATE INDEX IF NOT EXISTS mcp_oauth_tokens_expiry_idx ON public.mcp_oauth_tokens(expires_at);
CREATE INDEX IF NOT EXISTS mcp_oauth_codes_connection_idx ON public.mcp_oauth_codes(connection_id);
CREATE INDEX IF NOT EXISTS mcp_oauth_codes_expiry_idx ON public.mcp_oauth_codes(expires_at);
CREATE INDEX IF NOT EXISTS mcp_oauth_requests_expiry_idx ON public.mcp_oauth_requests(expires_at);
CREATE INDEX IF NOT EXISTS mcp_oauth_requests_client_idx ON public.mcp_oauth_requests(client_id);
CREATE TABLE IF NOT EXISTS public.mcp_oauth_rate_buckets (
  bucket text PRIMARY KEY,
  hits bigint NOT NULL DEFAULT 1,
  expires_at timestamptz NOT NULL
);
CREATE INDEX IF NOT EXISTS mcp_oauth_rate_expiry_idx ON public.mcp_oauth_rate_buckets(expires_at);

CREATE OR REPLACE FUNCTION public.mcp_oauth_take_rate(p_bucket text, p_limit integer, p_window_seconds integer)
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE n bigint;
BEGIN
  IF length(p_bucket) > 200 OR p_limit < 1 OR p_window_seconds < 1 OR p_window_seconds > 86400 THEN RETURN false; END IF;
  INSERT INTO public.mcp_oauth_rate_buckets AS b(bucket,hits,expires_at)
    VALUES(p_bucket,1,now()+make_interval(secs=>p_window_seconds))
    ON CONFLICT(bucket) DO UPDATE SET
      hits=CASE WHEN b.expires_at <= now() THEN 1 ELSE b.hits+1 END,
      expires_at=CASE WHEN b.expires_at <= now() THEN now()+make_interval(secs=>p_window_seconds) ELSE b.expires_at END
    RETURNING hits INTO n;
  -- Bounded housekeeping: never scan/delete an unbounded history in a public request.
  DELETE FROM public.mcp_oauth_rate_buckets WHERE bucket IN
    (SELECT bucket FROM public.mcp_oauth_rate_buckets WHERE expires_at < now()-interval '1 hour' LIMIT 100);
  DELETE FROM public.mcp_oauth_requests WHERE id IN
    (SELECT id FROM public.mcp_oauth_requests WHERE expires_at < now()-interval '1 hour' LIMIT 100);
  DELETE FROM public.mcp_oauth_codes WHERE code_hash IN
    (SELECT code_hash FROM public.mcp_oauth_codes WHERE expires_at < now()-interval '1 hour' LIMIT 100);
  DELETE FROM public.mcp_oauth_tokens WHERE token_hash IN
    (SELECT token_hash FROM public.mcp_oauth_tokens WHERE expires_at < now()-interval '1 hour' LIMIT 100);
  DELETE FROM public.mcp_oauth_connections WHERE id IN
    (SELECT id FROM public.mcp_oauth_connections WHERE expires_at < now()-interval '1 day' LIMIT 100);
  DELETE FROM public.mcp_oauth_clients WHERE client_id IN
    (SELECT c.client_id FROM public.mcp_oauth_clients c WHERE c.created_at < now()-interval '1 day'
      AND NOT EXISTS (SELECT 1 FROM public.mcp_oauth_connections g WHERE g.client_id=c.client_id)
      AND NOT EXISTS (SELECT 1 FROM public.mcp_oauth_requests r WHERE r.client_id=c.client_id) LIMIT 100);
  RETURN n <= p_limit;
END; $$;

CREATE OR REPLACE FUNCTION public.mcp_oauth_approve(
  p_request_id text,p_telegram_id bigint,p_group_id text,p_accept boolean,p_code_hash text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE r public.mcp_oauth_requests; cid uuid;
BEGIN
  IF p_request_id IS NULL OR p_telegram_id IS NULL OR p_group_id IS NULL OR p_accept IS NULL THEN
    RETURN jsonb_build_object('error','invalid_request');
  END IF;
  SELECT * INTO r FROM public.mcp_oauth_requests WHERE id=p_request_id FOR UPDATE;
  IF NOT FOUND OR r.consumed_at IS NOT NULL OR r.expires_at<=now() THEN RETURN jsonb_build_object('error','invalid_request'); END IF;
  -- Lock membership so a concurrent transfer/revocation cannot leave a surviving new grant.
  PERFORM 1 FROM public.allowed_users WHERE telegram_id=p_telegram_id AND group_id=p_group_id FOR SHARE;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','access_denied'); END IF;
  UPDATE public.mcp_oauth_requests SET consumed_at=now() WHERE id=r.id;
  IF p_accept THEN
    IF p_code_hash IS NULL OR p_code_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'invalid code hash'; END IF;
    INSERT INTO public.mcp_oauth_connections(telegram_id,group_id,client_id,redirect_uri,resource,scope)
      VALUES(p_telegram_id,p_group_id,r.client_id,r.redirect_uri,r.resource,r.scope) RETURNING id INTO cid;
    INSERT INTO public.mcp_oauth_codes(code_hash,connection_id,client_id,redirect_uri,challenge,resource)
      VALUES(p_code_hash,cid,r.client_id,r.redirect_uri,r.challenge,r.resource);
  END IF;
  RETURN jsonb_build_object('redirect_uri',r.redirect_uri,'state',r.state,'accepted',p_accept,'connection_id',cid);
END; $$;

CREATE OR REPLACE FUNCTION public.mcp_oauth_exchange(
  p_kind text,p_secret_hash text,p_client_id text,p_redirect_uri text,p_challenge text,p_resource text,
  p_access_hash text,p_refresh_hash text
) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE code public.mcp_oauth_codes; tok public.mcp_oauth_tokens; c public.mcp_oauth_connections;
  cid uuid; already_used boolean; access_expiry timestamptz;
BEGIN
  IF p_kind IS NULL OR p_secret_hash IS NULL OR p_client_id IS NULL OR p_resource IS NULL
    OR p_access_hash IS NULL OR p_refresh_hash IS NULL OR p_access_hash !~ '^[0-9a-f]{64}$' OR p_refresh_hash !~ '^[0-9a-f]{64}$'
    THEN RETURN jsonb_build_object('error','invalid_request'); END IF;
  IF p_kind='authorization_code' THEN
    IF p_redirect_uri IS NULL OR p_challenge IS NULL THEN RETURN jsonb_build_object('error','invalid_grant'); END IF;
    SELECT * INTO code FROM public.mcp_oauth_codes WHERE code_hash=p_secret_hash FOR UPDATE;
    IF NOT FOUND OR code.expires_at<=now() OR code.client_id<>p_client_id OR code.redirect_uri<>p_redirect_uri
      OR code.challenge<>p_challenge OR code.resource<>p_resource THEN RETURN jsonb_build_object('error','invalid_grant'); END IF;
    cid:=code.connection_id; already_used:=code.consumed_at IS NOT NULL;
  ELSIF p_kind='refresh_token' THEN
    SELECT * INTO tok FROM public.mcp_oauth_tokens WHERE token_hash=p_secret_hash AND kind='refresh' FOR UPDATE;
    IF NOT FOUND OR tok.expires_at<=now() THEN RETURN jsonb_build_object('error','invalid_grant'); END IF;
    cid:=tok.connection_id; already_used:=tok.consumed_at IS NOT NULL;
  ELSE RETURN jsonb_build_object('error','unsupported_grant_type'); END IF;
  SELECT * INTO c FROM public.mcp_oauth_connections WHERE id=cid FOR UPDATE;
  IF NOT FOUND OR c.client_id<>p_client_id OR c.resource<>p_resource OR c.expires_at<=now() OR c.revoked_at IS NOT NULL
    THEN RETURN jsonb_build_object('error','invalid_grant'); END IF;
  PERFORM 1 FROM public.allowed_users WHERE telegram_id=c.telegram_id AND group_id=c.group_id;
  IF NOT FOUND THEN
    UPDATE public.mcp_oauth_connections SET revoked_at=now() WHERE id=cid;
    RETURN jsonb_build_object('error','invalid_grant');
  END IF;
  IF already_used THEN
    -- Replay revokes the entire grant, including the successor pair from a racing refresh.
    UPDATE public.mcp_oauth_connections SET revoked_at=now() WHERE id=cid;
    RETURN jsonb_build_object('error','invalid_grant');
  END IF;
  IF p_kind='authorization_code' THEN
    UPDATE public.mcp_oauth_codes SET consumed_at=now() WHERE code_hash=p_secret_hash;
  ELSE
    UPDATE public.mcp_oauth_tokens SET consumed_at=now() WHERE token_hash=p_secret_hash;
  END IF;
  access_expiry:=least(now()+interval '1 hour',c.expires_at);
  INSERT INTO public.mcp_oauth_tokens(token_hash,connection_id,kind,expires_at) VALUES
    (p_access_hash,cid,'access',access_expiry),(p_refresh_hash,cid,'refresh',c.expires_at);
  RETURN jsonb_build_object('scope',c.scope,'expires_in',greatest(1,floor(extract(epoch FROM access_expiry-now()))),'connection_id',cid);
END; $$;

CREATE OR REPLACE FUNCTION public.mcp_oauth_resolve(p_token_hash text,p_resource text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE c public.mcp_oauth_connections;
BEGIN
  SELECT g.* INTO c FROM public.mcp_oauth_tokens t
    JOIN public.mcp_oauth_connections g ON g.id=t.connection_id
    JOIN public.allowed_users u ON u.telegram_id=g.telegram_id AND u.group_id=g.group_id
    WHERE t.token_hash=p_token_hash AND t.kind='access' AND t.expires_at>now()
      AND g.resource=p_resource AND g.scope IN ('mcp','mcp offline_access') AND g.expires_at>now() AND g.revoked_at IS NULL;
  IF NOT FOUND THEN RETURN NULL; END IF;
  UPDATE public.mcp_oauth_connections SET last_seen_at=now() WHERE id=c.id
    AND (last_seen_at IS NULL OR last_seen_at<now()-interval '1 minute') AND revoked_at IS NULL;
  RETURN jsonb_build_object('telegramId',c.telegram_id,'groupId',c.group_id,'connectionId',c.id);
END; $$;

CREATE OR REPLACE FUNCTION public.mcp_oauth_revoke(p_token_hash text,p_client_id text)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  UPDATE public.mcp_oauth_connections SET revoked_at=coalesce(revoked_at,now())
    WHERE client_id=p_client_id AND id IN (SELECT connection_id FROM public.mcp_oauth_tokens WHERE token_hash=p_token_hash);
END; $$;

CREATE OR REPLACE FUNCTION public.mcp_oauth_revoke_on_access_change()
RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.group_id IS DISTINCT FROM OLD.group_id OR NEW.is_admin IS DISTINCT FROM OLD.is_admin THEN
    UPDATE public.mcp_oauth_connections SET revoked_at=coalesce(revoked_at,now()) WHERE telegram_id=OLD.telegram_id AND revoked_at IS NULL;
  END IF;
  RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS allowed_users_revoke_oauth ON public.allowed_users;
CREATE TRIGGER allowed_users_revoke_oauth AFTER UPDATE OF group_id,is_admin ON public.allowed_users
  FOR EACH ROW EXECUTE FUNCTION public.mcp_oauth_revoke_on_access_change();

DO $$ DECLARE t text; BEGIN
  FOREACH t IN ARRAY ARRAY['mcp_oauth_clients','mcp_oauth_requests','mcp_oauth_connections','mcp_oauth_codes','mcp_oauth_tokens','mcp_oauth_rate_buckets'] LOOP
    EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
    EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);
    EXECUTE format('GRANT ALL ON public.%I TO service_role',t);
  END LOOP;
END; $$;
REVOKE ALL ON FUNCTION public.mcp_oauth_take_rate(text,integer,integer) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.mcp_oauth_approve(text,bigint,text,boolean,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.mcp_oauth_exchange(text,text,text,text,text,text,text,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.mcp_oauth_resolve(text,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.mcp_oauth_revoke(text,text) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.mcp_oauth_revoke_on_access_change() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.mcp_oauth_take_rate(text,integer,integer) TO service_role;
GRANT EXECUTE ON FUNCTION public.mcp_oauth_approve(text,bigint,text,boolean,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.mcp_oauth_exchange(text,text,text,text,text,text,text,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.mcp_oauth_resolve(text,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.mcp_oauth_revoke(text,text) TO service_role;
GRANT EXECUTE ON FUNCTION public.mcp_oauth_revoke_on_access_change() TO service_role;
